create table app_users(id varchar(36) primary key, username varchar(100) not null unique, password_hash varchar(100) not null, role varchar(10) not null, enabled boolean not null, created_at varchar(40) not null);
create table sessions(token_hash varchar(64) primary key, user_id varchar(36) not null references app_users(id), csrf varchar(100) not null, expires_at bigint not null);
create table projects(id varchar(36) primary key, name varchar(200) not null, description varchar(2000) not null, created_at varchar(40) not null);
create table memberships(project_id varchar(36) not null references projects(id), user_id varchar(36) not null references app_users(id), role varchar(10) not null, primary key(project_id,user_id));
create table materials(id varchar(36) primary key, project_id varchar(36) not null references projects(id), object_type varchar(20) not null, name varchar(200) not null, media_type varchar(120) not null, byte_size bigint not null, algorithm varchar(100), key_kind varchar(40), encoding varchar(10), usage_text varchar(500), description varchar(2000), fingerprint varchar(64), stateful boolean not null, pending boolean not null, created_at varchar(40) not null, updated_at varchar(40) not null);
create table jobs(id varchar(36) primary key, project_id varchar(36) not null references projects(id), user_id varchar(36) not null references app_users(id), tool_id varchar(100) not null, status varchar(20) not null, created_at varchar(40) not null, started_at varchar(40), finished_at varchar(40), exit_code int, duration_ms bigint, error_text varchar(300), stdout_preview varchar(8000), stderr_preview varchar(8000), truncated boolean not null);
create table artifacts(id varchar(36) primary key references materials(id), job_id varchar(36) not null references jobs(id), sensitive boolean not null);
create table audit_events(id varchar(36) primary key, project_id varchar(36), actor varchar(36) not null, action varchar(100) not null, resource_type varchar(30) not null, resource_id varchar(36), outcome varchar(30) not null, created_at varchar(40) not null);
create index audit_project on audit_events(project_id,created_at);
